def gen(rng):
    def name(i):
        return chr(97 + i // 26) + chr(97 + i % 26)
    def fmt(offs, ups):
        lines = [f'{len(offs)} {len(ups)}']
        for i, o in enumerate(offs):
            lines.append(f'{name(i)} {o}')
        for ts, p, c in ups:
            lines.append(f'{ts} {p} {name(c)}')
        return '\n'.join(lines)
    def rand_case(m, n, orange, tmax, pmax):
        offs = [rng.randint(-orange, orange) for _ in range(m)]
        ts = sorted(rng.randint(0, tmax) for _ in range(n))
        ups = [(t, rng.randint(1, pmax), rng.randrange(m)) for t in ts]
        return fmt(offs, ups)
    tests = [
        fmt([0], [(0, 1, 0)]),
        fmt([5], [(1, 5, 0), (1, 6, 0), (2, 7, 0)]),
        fmt([0, 0], [(1, 1, 0), (1, 2, 1), (1, 3, 0), (1, 4, 1)]),
        fmt([-10**9, 10**9], [(0, 1, 1), (10**9, 2, 0), (10**9, 3, 1)]),
        fmt([5, -3], [(10, 100, 0), (11, 200, 1), (12, 150, 0), (20, 90, 1)]),
    ]
    for m, n in ((2, 5), (3, 8), (4, 12), (5, 15), (2, 20), (6, 18)):
        for _ in range(3):
            tests.append(rand_case(m, n, rng.choice([0, 3, 10, 50]), rng.choice([5, 30, 200]), 99))
    tests.append(rand_case(1000, 20000, 1000, 10**9, 10**5))
    tests.append(rand_case(500, 100000, 10**9, 10**7, 10**5))
    tests.append(rand_case(1000, 100000, 1000, 10**5, 10**5))
    tests.append(rand_case(50, 100000, 10**6, 10**7, 10**5))
    return tests

